            cancellationToken.ThrowIfCancellationRequested();
            await ReconcileFromScheduleScheduleUserItems(items, attachChildSubscribe: false, cancellationToken);
            _mounted = true;
        }

        public void SubscribeFromScheduleScheduleUserData(Action? onChange = null, Action<Exception>? onError = null)
        {
            ThrowIfDisposed();
            if (_subscriptionActive) throw new InvalidOperationException("Already subscribed");
            _subscriptionActive = true;
            // Consumer-facing notification, wrapped once so a throwing consumer
            // callback routes to onError (or Debug) instead of escaping the
            // loader's async-void chain.
            Action notify = () =>
            {
                try { onChange?.Invoke(); }
                catch (Exception ex) { if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex); }
            };
            _onChange = notify;
            foreach (var b in _binders) b.Subscribe(notify);
            var arrayLoader = new Gs2Bind.Gs2Schedule.TriggerArrayLoader("Schedule");
            _unsubscribers.Add(arrayLoader.Subscribe(
                _gs2,
                _session,
                async (_, _, items) =>
                {
                    if (_disposed) return;
                    try
                    {
                        await ReconcileFromScheduleScheduleUserItems(items, attachChildSubscribe: true, CancellationToken.None);
                    }
                    catch (Exception ex)
                    {
                        if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex);
                    }
                },
                notify
            ));
        }

        private async Task ReconcileFromScheduleScheduleUserItems(IList<Gs2.Unity.Gs2Schedule.Model.EzTrigger> items, bool attachChildSubscribe, CancellationToken cancellationToken)
        {
            var seen = new HashSet<string>();
            foreach (var item in items)
            {
                if (_disposed) return;
                var rowKey = ExtractScheduleScheduleUserRowKey(item);
                if (rowKey == null) continue;
                seen.Add(rowKey);
                if (_bindersByRowKey.TryGetValue(rowKey, out var existing))
                {
                    ApplyScheduleScheduleUserItemTo(existing.MutableModel, item);
                }
                else
                {
                    var binder = await BuildBinderFromScheduleScheduleUserItem(item, cancellationToken);
                    if (_disposed)
                    {
                        binder.Dispose();
                        return;
                    }
                    if (_bindersByRowKey.TryGetValue(rowKey, out var raced))
                    {
                        ApplyScheduleScheduleUserItemTo(raced.MutableModel, item);
                        binder.Dispose();
                        continue;
                    }
                    if (attachChildSubscribe) binder.Subscribe(_onChange);
                    _bindersByRowKey[rowKey] = binder;
                    _binders.Add(binder);
                    ItemAdded?.Invoke(binder);
                }
            }
            if (_bindersByRowKey.Count > seen.Count)
            {
                var toRemove = new List<string>();
                foreach (var kv in _bindersByRowKey)
                {
                    if (!seen.Contains(kv.Key)) toRemove.Add(kv.Key);
                }
                // Detach every stale binder before callbacks; a callback may dispose this Collection.
                var pendingRemovals = new List<Action>();
                foreach (var rowKey in toRemove)
                {
                    if (!_bindersByRowKey.TryGetValue(rowKey, out var binder)) continue;
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    var detachedBinder = binder;
                    // Notify while the binder is live; the Collection retains disposal ownership.
                    pendingRemovals.Add(() =>
                    {
                        try
                        {
                            if (!_disposed) ItemRemoved?.Invoke(detachedBinder);
                        }
                        finally
                        {
                            detachedBinder.Dispose();
                        }
                    });
                }
                Exception? removalError = null;
                foreach (var remove in pendingRemovals)
                {
                    try { remove(); }
                    catch (Exception ex) { removalError ??= ex; }
                }
                if (removalError != null) throw removalError;
            }
            if (!_disposed) SortBinders();
        }

        private async Task<TriggerBinder> BuildBinderFromScheduleScheduleUserItem(Gs2.Unity.Gs2Schedule.Model.EzTrigger item, CancellationToken cancellationToken)
        {
            var model = TriggerBinder.CreateModel((string.IsNullOrEmpty(item.Name) ? default(TriggerId) : new TriggerId(item.Name)));
            ApplyScheduleScheduleUserItemTo(model, item);
            var binder = new TriggerBinder(model, _gs2, _session);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyScheduleScheduleUserItemTo(MutableTrigger model, Gs2.Unity.Gs2Schedule.Model.EzTrigger item)
        {
            TriggerBinder.ApplyUserdataScheduleTrigger(model, item);
        }

        private TriggerId ExtractScheduleScheduleUserIdentity(Gs2.Unity.Gs2Schedule.Model.EzTrigger item)
        {
            return (string.IsNullOrEmpty(item.Name) ? default(TriggerId) : new TriggerId(item.Name));
        }

        private string? ExtractScheduleScheduleUserRowKey(Gs2.Unity.Gs2Schedule.Model.EzTrigger item)
        {
            var id = ExtractScheduleScheduleUserIdentity(item);
            if (EqualityComparer<TriggerId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.Name)) return null;
            return $"{item.Name}";
        }

        internal sealed class TriggerBinderComparer : IComparer<IReadOnlyTriggerBinder>
        {
            public static readonly TriggerBinderComparer Default = new TriggerBinderComparer();
            public int Compare(IReadOnlyTriggerBinder? a, IReadOnlyTriggerBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<TriggerId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class TriggerBinderIdTieBreakComparer : IComparer<IReadOnlyTriggerBinder>
        {
            private readonly IComparer<IReadOnlyTriggerBinder> _inner;
            public TriggerBinderIdTieBreakComparer(IComparer<IReadOnlyTriggerBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyTriggerBinder? a, IReadOnlyTriggerBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<TriggerId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
